/* Six guardians share commitment timing; each chapter owns its safety geometry. */
const BeyondGuardians=(()=>{
  const alive=e=>e&&e.hp>0&&!e.killed,point=(x,y)=>World.clipToArena({x,y},90);
  const inArena=p=>{const a=World.arena();return Math.hypot((p.x-a.cx)/a.rx,(p.y-a.cy)/a.ry)<=1;};
  function segmentDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,k=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1)));return Math.hypot(p.x-a.x-k*dx,p.y-a.y-k*dy);}
  function polygonSafe(vertices,p){let area=0;for(let i=0;i<vertices.length;i++){const a=vertices[i],b=vertices[(i+1)%vertices.length];area+=a.x*b.y-b.x*a.y;}const sign=area>=0?1:-1;return vertices.every((a,i)=>{const b=vertices[(i+1)%vertices.length],dx=b.x-a.x,dy=b.y-a.y;return sign*(dx*(p.y-a.y)-dy*(p.x-a.x))>(p.r||0)*Math.hypot(dx,dy);});}
  function safe(t,p){const q=t.safe||t,x=p.x-q.x,y=p.y-q.y,r=p.r||0,a=t.safeAngle||0,u=x*Math.cos(a)+y*Math.sin(a),v=-x*Math.sin(a)+y*Math.cos(a);
    if(t.safeMode==='cross'){const arm=(u,v)=>Math.abs(u)>t.innerRadius+r&&Math.abs(u)<t.safeLength-r&&Math.abs(v)<t.safeWidth-r;return arm(u,v)||arm(v,u);}
    if(t.safeMode==='lens')return t.centers.every(c=>Math.hypot(p.x-c.x,p.y-c.y)<t.safeRadius-r);
    if(t.safeMode==='channel')return t.path.slice(1).some((b,i)=>segmentDistance(p,t.path[i],b)<t.safeWidth-r);
    if(t.safeMode==='diamond')return Math.abs(u)+Math.abs(v)<t.safeRadius-r*Math.SQRT2;
    if(t.safeMode==='bridge')return Math.abs(u)<t.safeLength-r&&Math.abs(v)<t.safeWidth+Math.abs(u)*t.slope-r*Math.sqrt(1+t.slope*t.slope);
    if(t.safeMode==='triangle')return polygonSafe(t.vertices,p);
    return Math.hypot(x,y)<t.safeRadius-r;
  }
  function safePoint(t){if(t.target)return t.target;if(t.safeMode==='cross'){const a=t.safeAngle||0,r=(t.innerRadius+t.safeLength)/2;return {x:t.x+Math.cos(a)*r,y:t.y+Math.sin(a)*r};}return t.safe||{x:t.x,y:t.y};}
  const wardHit=(t,p)=>inArena(p)&&Math.hypot(p.x-t.x,p.y-t.y)<t.zoneRadius+(p.r||0)&&!safe(t,p);
  function state(e,name,duration){e.action=name;e.actionT=0;e.actionDuration=duration;e.attack=['windup','strike'].includes(name)?duration:0;}
  function clear(e){G.telegraphs=G.telegraphs.filter(t=>t.bossOwner!==e.id);G.eshots=G.eshots.filter(t=>t.bossOwner!==e.id);e.brain.pending=null;}
  function init(e){e.brain={round:1,breaks:0,attackIndex:0,token:0,pending:null,windowDamage:0,duelFailures:0};e.phase=1;state(e,'guard',1.5);}
  function hazard(e,p,o){const pending=e.brain.pending,life=Math.max(.65,o.life*Journey.difficulty().warning);Journey.hazard(p.x,p.y,{...o,life,total:life,boss:true,bossOwner:e.id,bossToken:pending.token,theme:Journey.run.stage%3,chapterTheme:Journey.run.stage,damageContext:{kind:'boss',scale:e.threat?.damage||1,shieldFactor:1}});pending.expected++;pending.last=Math.max(pending.last,life);}
  function ritual(e,local,a){const base={shape:'beyond',zoneRadius:1000,r:180,dmg:62+local*2},center={x:a.cx,y:a.cy},at=(x,y)=>point(a.cx+x,a.cy+y),ward=(i,geometry,label)=>hazard(e,center,{...base,...geometry,life:3.8+i*4.2,label,bossSkill:'beyond-'+Journey.stage().strategy});
    if(local===0){for(let i=0;i<2;i++)ward(i,{safeMode:'cross',safeAngle:i*Math.PI/4,innerRadius:130,safeLength:430,safeWidth:95},i?'根火转向 · 斜向外臂':'四誓焚林 · 十字外臂');ward(2,{safeMode:'circle',safeRadius:175},'断誓归根 · 中央断结');}
    else if(local===1){ward(0,{safeMode:'circle',safe:at(-230,0),safeRadius:150},'本命灯起 · 守左灯');ward(1,{safeMode:'circle',safe:at(230,0),safeRadius:150},'借命灯起 · 守右灯');ward(2,{safeMode:'lens',centers:[at(-85,0),at(85,0)],safeRadius:200,target:center},'两灯对照 · 只站重叠交集');}
    else if(local===2){for(let i=0;i<2;i++){const sign=i?-1:1,path=[[-360,140],[-120,140],[-120,-180],[260,-180]].map(([x,y])=>at(x*sign,y*sign));ward(i,{safeMode:'channel',path,safeWidth:90,target:path[1]},i?'旧契折返 · 镜像青渠':'逆契潮起 · 沿青渠拐角');}ward(2,{safeMode:'circle',safeRadius:175},'债归其主 · 中央销契池');}
    else if(local===3){ward(0,{safeMode:'diamond',safe:at(-230,90),safeRadius:195},'初雷问令 · 左菱台');ward(1,{safeMode:'diamond',safe:at(230,-90),safeRadius:195},'二雷问利 · 右菱台');ward(2,{safeMode:'circle',safeRadius:175},'三雷问罪 · 中央断诏');}
    else if(local===4){ward(0,{safeMode:'bridge',safe:at(0,185),safeAngle:0,safeLength:440,safeWidth:85,slope:.19},'封河初冰 · 横向冰桥');ward(1,{safeMode:'bridge',safe:at(0,-185),safeAngle:Math.PI/2,safeLength:440,safeWidth:85,slope:.19},'冰脊翻转 · 纵向冰桥');ward(2,{safeMode:'circle',safeRadius:175},'明春不再等 · 中央融冰');}
    else{for(let i=0;i<3;i++){const q=at(...[[-220,110],[220,110],[0,-170]][i]),angle=-Math.PI/2+i*Math.PI*2/3;ward(i,{safeMode:'triangle',vertices:Array.from({length:3},(_,j)=>({x:q.x+Math.cos(angle+j*Math.PI*2/3)*205,y:q.y+Math.sin(angle+j*Math.PI*2/3)*205})),target:q},['一印还刀 · 三角印心','二印还枪 · 三角印心','三印还剑 · 三角印心'][i]);}}
  }
  function assault(e,local,a,angle,origin){const line=(offset,life,label,width=40)=>hazard(e,e,{shape:'line',angle:angle+offset,length:570,r:width,dmg:57+local*2,life,label,bossSkill:'beyond-assault-'+local});
    if(local===0){for(let i=-1;i<=1;i++)line(i*.58,1.3+Math.abs(i)*.65,'誓枪分焰 · 从枪隙穿过',32);}
    else if(local===1){for(let i=0;i<3;i++){const p=point(origin.x+(i-1)*175,origin.y+(i%2)*90);hazard(e,p,{r:115,dmg:60,life:1.45+i*.7,label:'三炉借火 · 避开延迟落焰'});}}
    else if(local===2){line(0,1.3,'逆契横流 · 避开红线',48);line(Math.PI/2,2.3,'回购暗潮 · 留意第二浪',48);}
    else if(local===3){for(let i=0;i<3;i++){const p=point(origin.x+(i-1)*205,origin.y+(i===1?0:150));hazard(e,p,{r:100,dmg:64,life:1.45+i*.65,label:'征雨雷诏 · 落雷位置已锁定'});}}
    else if(local===4){for(let i=0;i<2;i++)hazard(e,e,{shape:'annulus',r:220+i*180,width:42,dmg:64,life:1.5+i*1.2,label:i?'外层冰裂 · 留意第二环':'内层封冰 · 穿过冰隙'});}
    else{for(let i=-1;i<=1;i++)line(i*.88,1.45+Math.abs(i)*.6,'金环夺势 · 避开三道器影',34);}
    if(e.phase===2){if(local===2)hazard(e,origin,{shape:'annulus',r:245,width:45,dmg:65,life:3.3,label:'逆契回流 · 避开旧位潮环'});else if(local===3||local===4)line(Math.PI/2,3.35,local===3?'怒相追雷 · 留意回雷线':'碎冰枪返 · 第二道锁向',42);else hazard(e,origin,{r:150,dmg:63+local,life:3.3,label:['誓灰复燃 · 离开旧位','借命余火 · 离开旧位','','','','金环落印 · 离开旧位'][local]});}
  }
  function prepare(e,mechanism){const b=e.brain,local=Journey.run.stage-18,a=World.arena(),angle=Math.atan2(P.y-e.y,P.x-e.x),origin=point(P.x,P.y);e.attackAngle=angle;e.look=Math.cos(angle)<0?-1:1;b.pending={token:++b.token,kind:mechanism?['roots','lamps','channels','thunder','bridges','weapons'][local]:'assault',mechanism,expected:0,impacts:0,passed:true,last:0};b.mechanismReady=mechanism;
    if(mechanism)ritual(e,local,a);else assault(e,local,a,angle,origin);
    state(e,'windup',Math.min(...G.telegraphs.filter(t=>t.bossOwner===e.id&&t.bossToken===b.pending.token).map(t=>t.life)));if(mechanism)Sound.omen(Journey.run.stage);
  }
  function finish(e){const b=e.brain,p=b.pending;if(p?.mechanism&&p.impacts===p.expected&&p.passed){clear(e);b.breaks++;b.windowDamage=0;state(e,'exposed',Bosses.profiles[Journey.run.difficulty].window);Sound.weakness(Journey.run.stage);addText(e.x,e.y-155,['誓火断根','两灯还命','逆水销契','雷诏已断','冰心融愿','三印还器'][Journey.run.stage-18]+' · 伤害3倍',Journey.stage().color,20);Motion.emit('blast',e.x,e.y,{r:185,duration:.9,color:Journey.stage().color});return;}if(p?.mechanism){b.duelFailures++;addText(e.x,e.y-155,'破招未成 · 仍可持续攻击','#dec6ab',16);}b.pending=null;b.mechanismReady=false;state(e,'guard',e.phase===2?.85:1.25);}
  function update(e,dt){if(!e.brain)init(e);if(!alive(e))return;const b=e.brain;if(e.phase===1&&e.hp<=e.maxHp*.5){e.phase=2;Sound.guardian(Journey.run.stage,true);addText(e.x,e.y-160,Journey.stage().boss+' · 怒相',Journey.stage().color,20);}e.actionT+=dt;
    if(e.action==='exposed'){if(e.actionT>=e.actionDuration){b.round++;clear(e);b.mechanismReady=false;state(e,'guard',1.2);}return;}
    if(e.action==='guard'){const d=Math.hypot(P.x-e.x,P.y-e.y);if(d>300){const v=World.steer(e,P.x,P.y);e.x+=v.x*e.speed*dt;e.y+=v.y*e.speed*dt;World.resolve(e);e.moving=true;}else e.moving=false;if(e.actionT>=e.actionDuration){e.moving=false;b.attackIndex++;prepare(e,b.attackIndex%3===0);}}
    else if(e.action==='windup'&&e.actionT>=e.actionDuration)state(e,'strike',Math.max(.4,b.pending.last-e.actionDuration+.2));else if(e.action==='strike'&&e.actionT>=e.actionDuration)state(e,'recover',.9);else if(e.action==='recover'&&e.actionT>=e.actionDuration)finish(e);
  }
  function onImpact(t,hit){const e=G.boss,p=e?.brain?.pending;if(!alive(e)||!p||t.bossOwner!==e.id||t.bossToken!==p.token)return;p.impacts++;p.passed=p.passed&&!hit;if(t.shape==='beyond')p.passed=p.passed&&inArena(P)&&safe(t,P)&&Math.hypot(P.x-t.x,P.y-t.y)<t.zoneRadius;}
  function hud(e){const b=e?.brain;if(!b)return {title:'全程可攻击',hint:Journey.stage().tell,progress:0};const exposed=e.action==='exposed',p=b.pending,remaining=Math.max(0,e.actionDuration-e.actionT);return {title:exposed?'破绽 · 伤害3倍 · '+remaining.toFixed(1)+'秒':p?.mechanism?['四誓转根 · 跟随根道','双灯还命 · 认准交集','逆水销契 · 两次折返','先鼓后雷 · 菱台换位','冰脊渡愿 · 横纵转桥','三印还器 · 接回兵魂'][Journey.run.stage-18]:'可持续攻击 · 避开锁向与延迟招式',hint:Journey.stage().bonusTell,progress:exposed?remaining/e.actionDuration:p?.mechanism?p.impacts/p.expected:0,helpers:0,exposed,remaining:exposed?remaining:0,breaks:b.breaks,round:b.round,action:e.action};}
  return {init,update,onImpact,onHelperKilled(){},filterDamage:(e,d)=>e.locked?0:d,hud,wardHit,safe,safePoint,inArena};
})();

const BeyondArt=(()=>{
  const sheets=BeyondChapters.map(c=>{const im=new Image();im.src='assets/actors-'+c.id+'.webp';return im;}),props=['dacheng','dujie'].map(name=>{const im=new Image();im.src='assets/'+name+'-props.webp';return im;});let uv=null,propUV=null;
  function configure(actors,objects){uv=actors;propUV=objects;}
  function drawActor(e,row,size){const i=(e.family??Journey.run.stage)-18,im=sheets[i];if(!im?.complete||!im.naturalWidth||!uv)return false;const col=e.action==='windup'?2:e.action==='strike'?3:e.moving?Math.floor((e.walkDistance||0)/30)%2:0,[x,y,w,h,px,py]=uv[i][row][col],scale=size/uv[i][row][0][3];ctx.drawImage(im,x,y,w,h,(x-px)*scale,(y-py)*scale,w*scale,h*scale);return true;}
  function drawProp(pen,o,stage){const i=stage-18,g=Math.floor(i/3),col={gate:0,tree:1,rock:1,lantern:2,shrine:3}[o.kind],im=props[g];if(col===undefined||!im?.complete||!im.naturalWidth||!propUV)return false;const [x,y,w,h]=propUV[g][i%3][col],size=o.size||{gate:350,tree:300,rock:155,lantern:120,shrine:215}[o.kind],s=size/Math.max(w,h);pen.drawImage(im,x,y,w,h,-w*s/2,-h*s,w*s,h*s);return true;}
  function drawShot(s){const i=s.theme-18;ctx.save();ctx.translate(s.x,s.y);ctx.rotate(Math.atan2(s.vy,s.vx));ctx.fillStyle=s.color;ctx.strokeStyle=s.color;ctx.lineWidth=2;ctx.beginPath();if(i===0||i===3){ctx.moveTo(-17,-5);ctx.lineTo(-4,2);ctx.lineTo(2,-7);ctx.lineTo(18,0);ctx.lineTo(3,7);ctx.stroke();}else if(i===1){ctx.ellipse(-5,0,12,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffedaf';ctx.beginPath();ctx.ellipse(4,0,6,3,0,0,Math.PI*2);ctx.fill();}else if(i===2){ctx.moveTo(-18,7);ctx.quadraticCurveTo(-2,-12,18,0);ctx.quadraticCurveTo(0,-2,-18,7);ctx.fill();}else if(i===4){ctx.moveTo(18,0);ctx.lineTo(-6,-7);ctx.lineTo(-15,0);ctx.lineTo(-6,7);ctx.closePath();ctx.fill();}else{ctx.arc(0,0,11,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(-17,0);ctx.lineTo(17,0);ctx.stroke();}ctx.restore();}
  function polygon(vertices){ctx.beginPath();vertices.forEach((v,i)=>i?ctx.lineTo(v.x,v.y):ctx.moveTo(v.x,v.y));ctx.closePath();}
  function drawWard(t){if(G.telegraphs.some(q=>q.shape==='beyond'&&q.life<t.life))return;ctx.save();ctx.fillStyle='#bf384822';ctx.strokeStyle='#e38b83';ctx.lineWidth=2;ctx.beginPath();ctx.arc(t.x,t.y,t.zoneRadius,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#5fdcb34a';ctx.strokeStyle='#b5ffdb';ctx.lineWidth=4;const p=t.safe||t;
    if(t.safeMode==='channel'){ctx.beginPath();t.path.forEach((q,i)=>i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y));ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#b5ffdb';ctx.lineWidth=t.safeWidth*2;ctx.stroke();ctx.strokeStyle='#469c8870';ctx.lineWidth=t.safeWidth*2-8;ctx.stroke();}
    else if(t.safeMode==='triangle'){polygon(t.vertices);ctx.fill();ctx.stroke();}
    else if(t.safeMode==='lens'){ctx.save();const [a,b]=t.centers;ctx.beginPath();ctx.arc(a.x,a.y,t.safeRadius,0,Math.PI*2);ctx.clip();ctx.beginPath();ctx.arc(b.x,b.y,t.safeRadius,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();ctx.save();ctx.beginPath();ctx.arc(b.x,b.y,t.safeRadius,0,Math.PI*2);ctx.clip();ctx.beginPath();ctx.arc(a.x,a.y,t.safeRadius,0,Math.PI*2);ctx.stroke();ctx.restore();ctx.setLineDash([7,6]);ctx.strokeStyle='#a99d89';for(const q of t.centers){ctx.beginPath();ctx.arc(q.x,q.y,t.safeRadius,0,Math.PI*2);ctx.stroke();}ctx.setLineDash([]);}
    else{ctx.save();ctx.translate(p.x,p.y);ctx.rotate(t.safeAngle||0);ctx.beginPath();if(t.safeMode==='cross'){for(let i=0;i<4;i++){ctx.save();ctx.rotate(i*Math.PI/2);ctx.rect(t.innerRadius,-t.safeWidth,t.safeLength-t.innerRadius,t.safeWidth*2);ctx.restore();}}
      else if(t.safeMode==='diamond'){ctx.moveTo(0,-t.safeRadius);ctx.lineTo(t.safeRadius,0);ctx.lineTo(0,t.safeRadius);ctx.lineTo(-t.safeRadius,0);ctx.closePath();}
      else if(t.safeMode==='bridge'){const l=t.safeLength,w=t.safeWidth,s=w+l*t.slope;polygon([{x:-l,y:-s},{x:0,y:-w},{x:l,y:-s},{x:l,y:s},{x:0,y:w},{x:-l,y:s}]);}
      else ctx.arc(0,0,t.safeRadius,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();}
    const target=BeyondGuardians.safePoint(t);ctx.strokeStyle='#ffdf96';ctx.fillStyle='#ffdf96';ctx.lineWidth=3;ctx.beginPath();ctx.arc(target.x,target.y,20,0,Math.PI*2);ctx.stroke();ctx.font='21px KaiTi';ctx.textAlign='center';ctx.fillText(['誓','命','契','雷','渡','器'][Journey.run.stage-18],target.x,target.y+7);
    if(!BeyondGuardians.safe(t,P)){const angle=Math.atan2(target.y-P.y,target.x-P.x);ctx.save();ctx.translate(P.x+Math.cos(angle)*80,P.y+Math.sin(angle)*80);ctx.rotate(angle);ctx.fillStyle='#b4ffe0';ctx.beginPath();ctx.moveTo(14,0);ctx.lineTo(-8,-8);ctx.lineTo(-3,0);ctx.lineTo(-8,8);ctx.closePath();ctx.fill();ctx.restore();}
    const label=t.label+' · '+Math.max(0,t.life).toFixed(1)+'秒';ctx.font='bold 16px KaiTi';ctx.strokeStyle='#08151c';ctx.lineWidth=5;ctx.strokeText(label,P.x,P.y-145);ctx.fillStyle='#f5e6cb';ctx.fillText(label,P.x,P.y-145);ctx.restore();}
  function drawEffect(e,p,fade){ctx.save();ctx.globalAlpha=fade*.7;ctx.strokeStyle=Journey.stages[e.chapterTheme].color;ctx.lineWidth=3;ctx.translate(e.x,e.y);const i=e.chapterTheme-18,r=Math.min(210,e.r||110)*(1+p*.4);if(i===0||i===3){ctx.rotate(p*.5);for(let n=0;n<4;n++){ctx.rotate(Math.PI/2);ctx.beginPath();ctx.moveTo(30,0);ctx.lineTo(r,0);ctx.lineTo(r*.7,-22);ctx.stroke();}}else if(i===1||i===5){for(let n=0;n<3;n++){ctx.beginPath();ctx.arc((n-1)*r*.35,0,r*.6,0,Math.PI*2);ctx.stroke();}}else{for(let n=0;n<3;n++){ctx.beginPath();ctx.ellipse(0,0,r*(1-n*.25),r*(.55-n*.1),0,0,Math.PI*2);ctx.stroke();}}ctx.restore();}
  return {configure,drawActor,drawProp,drawShot,drawWard,drawEffect,loaded:()=>!!uv&&!!propUV&&sheets.every(s=>s.complete&&s.naturalWidth)&&props.every(s=>s.complete&&s.naturalWidth)};
})();
BeyondChapters.forEach((c,i)=>{const s=i+18;Sound.registerCaption('stage-'+s,'说书人',c.story[0]);Sound.registerCaption('boss-'+s,c.boss,c.bossLine);Sound.registerCaption('phase-'+s,c.boss,['烧尽根，誓言也不会放过你！','忘了自己还剩几年，就不必来催账！','你不欠，未出生的人也得欠！','天雷已落，谁敢说是我下的令！','春天总会来，只要你们继续等！','兵器入环，反抗的名字也一并入账！'][i]);Sound.registerCaption('omen-'+s,'剑仙',['先走十字外臂，再跟斜根，最后回中央！','守左灯，守右灯，再站进两灯交集！','看青色折返水道，换路后再回池心！','两座菱台依次走，最后回中央断诏！','横冰桥，纵冰桥，最后去融冰圈！','三枚三角印，接回兵魂再出剑！'][i]);Sound.registerCaption('weakness-'+s,'剑仙',['焦根断了，让活人自己解誓！','两灯对照，把明日还回来！','逆水向前，旧债去找真正的主人！','雷诏已断，天意不归账房！','冰心融开，不必再等明春！','三印还器，自己的剑自己握住！'][i]);Sound.registerCaption('victory-'+s,'说书人',c.reveal);});
